document.getElementById('error-date').textContent='';
}

// Time
if(time===''){
errors.push('请选择时间段');
document.getElementById('error-time').textContent='请选择时间段';
}else{
document.getElementById('error-time').textContent='';
}

if(errors.length>0){
alert('请填写必填项：\n' + errors.join('\n'));
return false;
}
alert('预约成功！我们将在24小时内与您联系。');
return true;
}
